CREATE OR REPLACE FUNCTION calculate_wage_difference(
    offered_wage TEXT,
    prevailing_wage TEXT,
    wage_unit enum_wage_unit_of_pay,
    pw_unit enum_pw_unit_of_pay
) RETURNS NUMERIC AS $$
DECLARE
    offered_val NUMERIC;
    prevailing_val NUMERIC;
    offered_annual NUMERIC;
    prevailing_annual NUMERIC;
BEGIN
    -- Parse the wage values from text (remove $, commas, etc.)
    offered_val := REPLACE(REPLACE(offered_wage, '$', ''), ',', '')::NUMERIC;
    prevailing_val := REPLACE(REPLACE(prevailing_wage, '$', ''), ',', '')::NUMERIC;

    -- Convert offered wage to annual
    CASE wage_unit
        WHEN 'Hour' THEN offered_annual := offered_val * 2080
        WHEN 'Week' THEN offered_annual := offered_val * 52
        WHEN 'Month' THEN offered_annual := offered_val * 12
        ELSE offered_annual := offered_val
    END;

    -- Convert prevailing wage to annual
    CASE pw_unit
        WHEN 'Hour' THEN prevailing_annual := prevailing_val * 2080
        WHEN 'Week' THEN prevailing_annual := prevailing_val * 52
        WHEN 'Month' THEN prevailing_annual := prevailing_val * 12
        ELSE prevailing_annual := prevailing_val
    END;

    -- Return NULL if prevailing annual wage is 0
    IF prevailing_annual = 0 THEN
        RETURN NULL;
    END IF;

    -- Calculate and return WDR rounded to 2 decimal places
    RETURN ROUND(CAST(((offered_annual - prevailing_annual) / prevailing_annual) * 100 AS NUMERIC), 2);
END;
$$ LANGUAGE plpgsql;

